//! Golden vectors against colour-science 0.4.7, generated by `tools/golden/gen_cam16.py`.

use std::collections::BTreeMap;

use looklab_color::WhiteRelativeXyz;
use looklab_color::Xyz;
use looklab_color::cam16::{Cam16Model, Chroma, Jmh, Surround, ViewingConditions};
use looklab_color::ucs::{
    Ucs, UcsSpace, delta_e_lcd, delta_e_scd, delta_e_ucs, jmh_to_ucs, ucs_to_jmh,
};
use proptest::prelude::*;
use serde::Deserialize;

const FORWARD_JSON: &str = include_str!("golden/cam16_forward.json");
const INVERSE_JSON: &str = include_str!("golden/cam16_inverse.json");
const UCS_JSON: &str = include_str!("golden/cam16_ucs.json");

const FORWARD_TOL: f64 = 1e-6;
const INVERSE_TOL: f64 = 1e-5;

#[derive(Deserialize)]
struct ConditionJson {
    white: [f64; 3],
    l_a: f64,
    y_b: f64,
    surround: String,
    discount_illuminant: bool,
}

impl ConditionJson {
    fn model(&self) -> Cam16Model {
        let surround = match self.surround.as_str() {
            "Average" => Surround::Average,
            "Dim" => Surround::Dim,
            "Dark" => Surround::Dark,
            other => panic!("unknown surround {other}"),
        };
        Cam16Model::new(&ViewingConditions {
            white: Xyz::from_array(self.white),
            l_a: self.l_a,
            y_b: self.y_b,
            surround,
            discount_illuminant: self.discount_illuminant,
        })
    }
}

#[derive(Deserialize)]
struct ForwardFile {
    conditions: BTreeMap<String, ConditionJson>,
    forward: Vec<ForwardEntry>,
    ucs_j: Vec<UcsJEntry>,
}

#[derive(Deserialize)]
struct ForwardEntry {
    condition: String,
    xyz: [f64; 3],
    j: f64,
    c: f64,
    h: f64,
    m: f64,
    s: f64,
    q: f64,
}

#[derive(Deserialize)]
struct UcsJEntry {
    condition: String,
    xyz_at_unit_y: [f64; 3],
    y: f64,
    j_prime: f64,
}

#[derive(Deserialize)]
struct InverseFile {
    inverse: Vec<InverseEntry>,
}

#[derive(Deserialize)]
struct InverseEntry {
    condition: String,
    j: f64,
    m: f64,
    c: f64,
    h: f64,
    xyz_m: [f64; 3],
    xyz_c: [f64; 3],
}

#[derive(Deserialize)]
struct UcsFile {
    forward: Vec<UcsForwardEntry>,
    inverse: Vec<UcsInverseEntry>,
    delta_e: Vec<DeltaEEntry>,
}

#[derive(Deserialize)]
struct UcsForwardEntry {
    space: String,
    jmh: [f64; 3],
    ucs: [f64; 3],
}

#[derive(Deserialize)]
struct UcsInverseEntry {
    space: String,
    ucs: [f64; 3],
    jmh: [f64; 3],
}

#[derive(Deserialize)]
struct DeltaEEntry {
    space: String,
    a: [f64; 3],
    b: [f64; 3],
    de: f64,
}

fn space(name: &str) -> UcsSpace {
    match name {
        "Ucs" => UcsSpace::Ucs,
        "Lcd" => UcsSpace::Lcd,
        "Scd" => UcsSpace::Scd,
        other => panic!("unknown space {other}"),
    }
}

/// Relative comparison with a magnitude floor.
fn close(got: f64, want: f64, tol: f64) -> bool {
    (got - want).abs() <= tol * want.abs().max(1e-3)
}

/// Angular difference in degrees, wrapped to `[0, 180]`.
fn hue_distance(a: f64, b: f64) -> f64 {
    let d = (a - b).abs() % 360.0;
    if d > 180.0 { 360.0 - d } else { d }
}

fn forward_file() -> ForwardFile {
    serde_json::from_str(FORWARD_JSON).expect("cam16_forward.json parses")
}

fn inverse_file() -> InverseFile {
    serde_json::from_str(INVERSE_JSON).expect("cam16_inverse.json parses")
}

fn ucs_file() -> UcsFile {
    serde_json::from_str(UCS_JSON).expect("cam16_ucs.json parses")
}

#[test]
fn forward_matches_colour_science() {
    let file = forward_file();
    let models: BTreeMap<_, _> = file
        .conditions
        .iter()
        .map(|(name, condition)| (name.clone(), condition.model()))
        .collect();

    for entry in &file.forward {
        let model = &models[&entry.condition];
        let cam = model.xyz_to_cam16(Xyz::from_array(entry.xyz));
        let label = format!("{} {:?}", entry.condition, entry.xyz);

        assert!(
            close(cam.j, entry.j, FORWARD_TOL),
            "J {label}: {} vs {}",
            cam.j,
            entry.j
        );
        assert!(
            close(cam.q, entry.q, FORWARD_TOL),
            "Q {label}: {} vs {}",
            cam.q,
            entry.q
        );
        // Chroma, saturation and hue are rounding noise on a neutral.
        if entry.c.abs() > 1e-3 {
            assert!(
                close(cam.c, entry.c, FORWARD_TOL),
                "C {label}: {} vs {}",
                cam.c,
                entry.c
            );
            assert!(
                close(cam.m, entry.m, FORWARD_TOL),
                "M {label}: {} vs {}",
                cam.m,
                entry.m
            );
            assert!(
                close(cam.s, entry.s, FORWARD_TOL),
                "s {label}: {} vs {}",
                cam.s,
                entry.s
            );
            assert!(
                hue_distance(cam.h, entry.h) <= FORWARD_TOL * 360.0,
                "h {label}: {} vs {}",
                cam.h,
                entry.h
            );
        }
    }
}

#[test]
fn inverse_matches_colour_science() {
    let file = forward_file();
    let models: BTreeMap<_, _> = file
        .conditions
        .iter()
        .map(|(name, condition)| (name.clone(), condition.model()))
        .collect();

    for entry in &inverse_file().inverse {
        let model = &models[&entry.condition];
        let label = format!("{} J={} h={}", entry.condition, entry.j, entry.h);

        let from_m = model.cam16_to_xyz(entry.j, Chroma::M(entry.m), entry.h);
        for (got, (want, axis)) in from_m
            .to_array()
            .into_iter()
            .zip(entry.xyz_m.into_iter().zip(["X", "Y", "Z"]))
        {
            assert!(
                close(got, want, INVERSE_TOL),
                "JMh -> XYZ_{axis} {label}: {got} vs {want}"
            );
        }

        let from_c = model.cam16_to_xyz(entry.j, Chroma::C(entry.c), entry.h);
        for (got, (want, axis)) in from_c
            .to_array()
            .into_iter()
            .zip(entry.xyz_c.into_iter().zip(["X", "Y", "Z"]))
        {
            assert!(
                close(got, want, INVERSE_TOL),
                "JCh -> XYZ_{axis} {label}: {got} vs {want}"
            );
        }
    }
}

#[test]
fn ucs_matches_colour_science() {
    let file = ucs_file();

    for entry in &file.forward {
        let got = jmh_to_ucs(
            Jmh {
                j: entry.jmh[0],
                m: entry.jmh[1],
                h: entry.jmh[2],
            },
            space(&entry.space),
        );
        for (got, want, axis) in [
            (got.j, entry.ucs[0], "J'"),
            (got.a, entry.ucs[1], "a'"),
            (got.b, entry.ucs[2], "b'"),
        ] {
            assert!(
                close(got, want, FORWARD_TOL),
                "{} JMh -> {axis}: {got} vs {want}",
                entry.space
            );
        }
    }

    for entry in &file.inverse {
        let got = ucs_to_jmh(Ucs::from_array(entry.ucs), space(&entry.space));
        assert!(
            close(got.j, entry.jmh[0], FORWARD_TOL),
            "{} UCS -> J: {} vs {}",
            entry.space,
            got.j,
            entry.jmh[0]
        );
        assert!(
            close(got.m, entry.jmh[1], FORWARD_TOL),
            "{} UCS -> M: {} vs {}",
            entry.space,
            got.m,
            entry.jmh[1]
        );
        if entry.jmh[1] > 1e-2 {
            assert!(
                hue_distance(got.h, entry.jmh[2]) <= FORWARD_TOL * 360.0,
                "{} UCS -> h: {} vs {}",
                entry.space,
                got.h,
                entry.jmh[2]
            );
        }
    }

    for entry in &file.delta_e {
        let a = Ucs::from_array(entry.a);
        let b = Ucs::from_array(entry.b);
        let got = match space(&entry.space) {
            UcsSpace::Ucs => delta_e_ucs(a, b),
            UcsSpace::Lcd => delta_e_lcd(a, b),
            UcsSpace::Scd => delta_e_scd(a, b),
        };
        assert!(
            close(got, entry.de, FORWARD_TOL),
            "{} delta E: {got} vs {}",
            entry.space,
            entry.de
        );
    }
}

#[test]
fn j_prime_matches_colour_science() {
    let file = forward_file();
    let models: BTreeMap<_, _> = file
        .conditions
        .iter()
        .map(|(name, condition)| (name.clone(), condition.model()))
        .collect();

    for entry in &file.ucs_j {
        let model = &models[&entry.condition];
        let (j_prime, _) = model.ucs_j_and_dj_dy(Xyz::from_array(entry.xyz_at_unit_y), entry.y);
        assert!(
            close(j_prime, entry.j_prime, FORWARD_TOL),
            "{} J' at y={}: {j_prime} vs {}",
            entry.condition,
            entry.y,
            entry.j_prime
        );
    }
}

#[test]
fn ucs_j_derivative_matches_central_difference() {
    let model = Cam16Model::new(&ViewingConditions::reference());
    let chromaticities = [
        Xyz::new(0.950_455_927_051_671_6, 1.0, 1.089_057_750_759_878_4),
        Xyz::new(0.3, 1.0, 0.5),
        Xyz::new(0.9, 1.0, 0.2),
        Xyz::new(0.05, 1.0, 0.1),
    ];

    for xyz_at_unit_y in chromaticities {
        for y in [0.02, 0.18, 0.5, 1.0] {
            let (_, analytic) = model.ucs_j_and_dj_dy(xyz_at_unit_y, y);
            let at = |yy: f64| {
                let cam = model.xyz_to_cam16(xyz_at_unit_y.scale(yy));
                jmh_to_ucs(
                    Jmh {
                        j: cam.j,
                        m: cam.m,
                        h: cam.h,
                    },
                    UcsSpace::Ucs,
                )
                .j
            };
            let step = 1e-6 * y;
            let numeric = (at(y + step) - at(y - step)) / (2.0 * step);
            let scale = analytic.abs().max(numeric.abs());
            assert!(
                (analytic - numeric).abs() <= 1e-6 * scale,
                "dJ'/dY at {:?}, y={y}: {analytic} vs {numeric}",
                xyz_at_unit_y
            );
        }
    }
}

#[test]
fn ucs_j_derivative_at_zero_is_infinite() {
    let model = Cam16Model::new(&ViewingConditions::reference());
    for chromaticity in [
        ViewingConditions::reference().white,
        Xyz::new(0.3, 1.0, 0.5),
        Xyz::new(0.0, 1.0, -1.0),
    ] {
        let (j_prime, slope) = model.ucs_j_and_dj_dy(chromaticity, 0.0);
        assert!(j_prime.is_finite(), "J' = {j_prime}");
        assert!(slope.is_infinite() && slope > 0.0, "dJ'/dY = {slope}");
    }
}

#[test]
fn reference_neutral_has_zero_ucs_chroma() {
    let conditions = ViewingConditions::reference();
    let model = Cam16Model::new(&conditions);

    for y in [0.005, 0.02, 0.18, 0.5, 1.0, 2.0] {
        let cam = model.xyz_to_cam16(conditions.white.scale(y));
        let ucs = jmh_to_ucs(
            Jmh {
                j: cam.j,
                m: cam.m,
                h: cam.h,
            },
            UcsSpace::Ucs,
        );
        assert!(ucs.a.abs() < 1e-12, "a' = {} at Y = {y}", ucs.a);
        assert!(ucs.b.abs() < 1e-12, "b' = {} at Y = {y}", ucs.b);
    }
}

#[test]
fn opponent_chroma_maps_reproduce_cam16_ucs() {
    let conditions = ViewingConditions::reference();
    let model = Cam16Model::new(&conditions);
    let scale = model.neutral_chroma_scale(conditions.white.scale(0.18), 2.0);
    let mut state = 0x9e37_79b9_7f4a_7c15_u64;
    let mut next = || {
        state = state
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        (state >> 11) as f64 / (1u64 << 53) as f64
    };
    for _ in 0..200 {
        let xyz = Xyz::new(
            0.05 + 1.2 * next(),
            0.05 + 1.2 * next(),
            0.05 + 1.2 * next(),
        );
        let opponent = model.cone_opponent(xyz);
        let n = [
            scale * opponent.a / opponent.denominator,
            scale * opponent.b / opponent.denominator,
        ];
        let cam = model.xyz_to_cam16(xyz);
        let ucs = jmh_to_ucs(
            Jmh {
                j: cam.j,
                m: cam.m,
                h: cam.h,
            },
            UcsSpace::Ucs,
        );
        let phi = model.ucs_chroma_from_opponent(n, ucs.j, scale);
        assert!(close(phi[0], ucs.a, 1e-9), "a' {} vs {}", phi[0], ucs.a);
        assert!(close(phi[1], ucs.b, 1e-9), "b' {} vs {}", phi[1], ucs.b);
        let psi = model.opponent_chroma_from_ucs([ucs.a, ucs.b], ucs.j, scale);
        assert!(close(psi[0], n[0], 1e-9), "n_a {} vs {}", psi[0], n[0]);
        assert!(close(psi[1], n[1], 1e-9), "n_b {} vs {}", psi[1], n[1]);
        let back = model.opponent_chroma_to_xyz(n, ucs.j, scale);
        assert!(close(back.x, xyz.x, 1e-7), "X {} vs {}", back.x, xyz.x);
        assert!(close(back.y, xyz.y, 1e-7), "Y {} vs {}", back.y, xyz.y);
        assert!(close(back.z, xyz.z, 1e-7), "Z {} vs {}", back.z, xyz.z);
    }
}

#[test]
fn opponent_chroma_jacobian_matches_finite_difference() {
    let conditions = ViewingConditions::reference();
    let model = Cam16Model::new(&conditions);
    let scale = model.neutral_chroma_scale(conditions.white.scale(0.18), 2.0);
    let h = 1e-6;
    for n in [[0.3, -0.2], [1.1, 0.7], [-0.5, 1.4], [0.05, 0.02]] {
        let j_prime = 55.0;
        let (jacobian, gradient) = model.ucs_chroma_from_opponent_jacobian(n, j_prime, scale);
        for axis in 0..2 {
            let mut plus = n;
            let mut minus = n;
            plus[axis] += h;
            minus[axis] -= h;
            let a = model.ucs_chroma_from_opponent(plus, j_prime, scale);
            let b = model.ucs_chroma_from_opponent(minus, j_prime, scale);
            for row in 0..2 {
                let numerical = (a[row] - b[row]) / (2.0 * h);
                let scale = numerical.abs().max(1.0);
                assert!(
                    (jacobian[row][axis] - numerical).abs() < 1e-6 * scale,
                    "n {n:?} row {row} axis {axis}: {} vs {numerical}",
                    jacobian[row][axis]
                );
            }
        }
        let a = model.ucs_chroma_from_opponent(n, j_prime + h, scale);
        let b = model.ucs_chroma_from_opponent(n, j_prime - h, scale);
        for row in 0..2 {
            let numerical = (a[row] - b[row]) / (2.0 * h);
            let scale = numerical.abs().max(1.0);
            assert!(
                (gradient[row] - numerical).abs() < 1e-6 * scale,
                "n {n:?} row {row}: {} vs {numerical}",
                gradient[row]
            );
        }
    }
}

#[test]
fn opponent_chroma_jacobian_is_nan_at_neutral_internal_chroma() {
    let conditions = ViewingConditions::reference();
    let model = Cam16Model::new(&conditions);
    let scale = model.neutral_chroma_scale(conditions.white.scale(0.18), 2.0);
    let (jacobian, gradient) = model.ucs_chroma_from_opponent_jacobian([0.0, 0.0], 55.0, scale);
    assert!(jacobian.iter().flatten().all(|value| value.is_nan()));
    assert!(gradient.iter().all(|value| value.is_nan()));
}

#[test]
fn cartesian_opponent_responses_match_the_ucs_inverse_and_differences() {
    let conditions = ViewingConditions::reference();
    let model = Cam16Model::new(&conditions);
    let scale = model.neutral_chroma_scale(conditions.white.scale(0.18), 2.0);
    for j_prime in [20.0, 50.0, 80.0] {
        for n in [
            [0.0, 0.0],
            [0.3, -0.2],
            [1.1, 0.7],
            [-0.5, 1.4],
            [0.05, 0.02],
        ] {
            let direct = model.opponent_chroma_response_derivatives(n, j_prime, scale);
            let xyz = model.opponent_chroma_to_xyz(n, j_prime, scale);
            let forward = model.cone_opponent(xyz).rgb_a;
            let chroma = model.ucs_chroma_from_opponent(n, j_prime, scale);
            let jmh = ucs_to_jmh(Ucs::new(j_prime, chroma[0], chroma[1]), UcsSpace::Ucs);
            let round_trip = model.inverse_responses(jmh);
            for channel in 0..3 {
                let magnitude = round_trip[channel].abs().max(1e-3);
                assert!(
                    (direct.responses[channel] - round_trip[channel]).abs() / magnitude < 1e-6,
                    "j {j_prime} n {n:?} channel {channel}: {} vs {}",
                    direct.responses[channel],
                    round_trip[channel]
                );
                assert!(
                    (direct.responses[channel] - forward[channel]).abs() / magnitude < 1e-6,
                    "forward j {j_prime} n {n:?} channel {channel}: {} vs {}",
                    direct.responses[channel],
                    forward[channel]
                );
            }
            let step = 1e-6;
            for axis in 0..3 {
                let plus = if axis == 0 {
                    model.opponent_chroma_response_derivatives(n, j_prime + step, scale)
                } else {
                    let mut moved = n;
                    moved[axis - 1] += step;
                    model.opponent_chroma_response_derivatives(moved, j_prime, scale)
                };
                let minus = if axis == 0 {
                    model.opponent_chroma_response_derivatives(n, j_prime - step, scale)
                } else {
                    let mut moved = n;
                    moved[axis - 1] -= step;
                    model.opponent_chroma_response_derivatives(moved, j_prime, scale)
                };
                for channel in 0..3 {
                    let numerical =
                        (plus.responses[channel] - minus.responses[channel]) / (2.0 * step);
                    let analytic = direct.first[channel][axis];
                    let magnitude = analytic.abs().max(numerical.abs()).max(1e-6);
                    assert!(
                        (analytic - numerical).abs() / magnitude < 1e-5,
                        "j {j_prime} n {n:?} channel {channel} axis {axis}: {analytic} vs {numerical}"
                    );
                }
            }
        }
    }
}

#[test]
fn ucs_response_derivatives_match_differences() {
    let model = Cam16Model::new(&ViewingConditions::reference());
    for (j_prime, chroma) in [(50.0, [30.0, -20.0]), (80.0, [-5.0, 8.0])] {
        let direct = model.ucs_chroma_response_derivatives(chroma, j_prime);
        let value = |j: f64, a: f64, b: f64| {
            model.inverse_responses(ucs_to_jmh(Ucs::new(j, a, b), UcsSpace::Ucs))
        };
        let base = value(j_prime, chroma[0], chroma[1]);
        for (channel, base_response) in base.iter().enumerate() {
            let magnitude = base_response.abs().max(1e-3);
            assert!(
                (direct.responses[channel] - *base_response).abs() / magnitude < 1e-12,
                "j {j_prime} chroma {chroma:?} channel {channel}: {} vs {}",
                direct.responses[channel],
                base_response
            );
        }
        let step = 1e-6;
        for axis in 0..3 {
            let plus = if axis == 0 {
                value(j_prime + step, chroma[0], chroma[1])
            } else if axis == 1 {
                value(j_prime, chroma[0] + step, chroma[1])
            } else {
                value(j_prime, chroma[0], chroma[1] + step)
            };
            let minus = if axis == 0 {
                value(j_prime - step, chroma[0], chroma[1])
            } else if axis == 1 {
                value(j_prime, chroma[0] - step, chroma[1])
            } else {
                value(j_prime, chroma[0], chroma[1] - step)
            };
            for channel in 0..3 {
                let numerical = (plus[channel] - minus[channel]) / (2.0 * step);
                let analytic = direct.first[channel][axis];
                let magnitude = analytic.abs().max(numerical.abs()).max(1e-6);
                assert!(
                    (analytic - numerical).abs() / magnitude < 1e-5,
                    "j {j_prime} chroma {chroma:?} channel {channel} axis {axis}: {analytic} vs {numerical}"
                );
            }
        }
    }
}

#[test]
fn computed_adaptation_matches_documented_reference_value() {
    let conditions = ViewingConditions {
        discount_illuminant: false,
        ..ViewingConditions::reference()
    };
    let d = conditions.degree_of_adaptation();
    assert!((d - 0.832).abs() < 1e-3, "D = {d}");
}

proptest! {
    #[test]
    fn xyz_cam16_round_trip(x in 0.02f64..1.0, y in 0.02f64..1.0, z in 0.02f64..1.0) {
        let model = Cam16Model::new(&ViewingConditions::reference());
        let xyz = Xyz::new(x, y, z);
        let cam = model.xyz_to_cam16(xyz);
        // CAM16 inverse requires positive lightness and chroma; a strongly blue,
        // low-luminance corner drives the achromatic response negative.
        prop_assume!(cam.j > 0.0 && cam.c > 0.0);
        let back = model.jmh_to_xyz(Jmh { j: cam.j, m: cam.m, h: cam.h });
        prop_assert!(close(back.x, xyz.x, 1e-7), "X: {} vs {}", back.x, xyz.x);
        prop_assert!(close(back.y, xyz.y, 1e-7), "Y: {} vs {}", back.y, xyz.y);
        prop_assert!(close(back.z, xyz.z, 1e-7), "Z: {} vs {}", back.z, xyz.z);
    }

    #[test]
    fn jmh_ucs_round_trip(j in 0.01f64..100.0, m in 0.0f64..100.0, h in 0.0f64..360.0) {
        let space = UcsSpace::Ucs;
        let jmh = Jmh { j, m, h };
        let back = ucs_to_jmh(jmh_to_ucs(jmh, space), space);
        prop_assert!(close(back.j, j, 1e-9), "J: {} vs {}", back.j, j);
        prop_assert!(close(back.m, m, 1e-9), "M: {} vs {}", back.m, m);
        let hr = h * (core::f64::consts::PI / 180.0);
        let (sa, sb) = (m * libm::cos(hr), m * libm::sin(hr));
        let br = back.h * (core::f64::consts::PI / 180.0);
        let (ba, bb) = (back.m * libm::cos(br), back.m * libm::sin(br));
        prop_assert!((ba - sa).abs() <= 1e-9 * sa.abs().max(1e-3), "a: {} vs {}", ba, sa);
        prop_assert!((bb - sb).abs() <= 1e-9 * sb.abs().max(1e-3), "b: {} vs {}", bb, sb);
    }
}

#[test]
fn near_neutral_departure_keeps_the_forward_chroma() {
    let model = Cam16Model::new(&ViewingConditions::reference());

    let neutral = model.xyz_departure_to_cam16(WhiteRelativeXyz::from_array([0.0, 0.0, 0.0]));
    assert_eq!(neutral.j, 100.0);
    assert_eq!(neutral.c, 0.0);
    assert_eq!(neutral.m, 0.0);

    let departure = WhiteRelativeXyz::from_array([1.0e-16, -2.0e-16, 3.0e-17]);
    let cam = model.xyz_departure_to_cam16(departure);
    let ucs = jmh_to_ucs(
        Jmh {
            j: cam.j,
            m: cam.m,
            h: cam.h,
        },
        UcsSpace::Ucs,
    );
    assert!(ucs.a.is_finite() && ucs.b.is_finite());
    assert!(ucs.a != 0.0 || ucs.b != 0.0);
    assert!(cam.c > 0.0 && cam.c.is_finite());
}
